{"cards": [{"node_code": "N_506a3eef6d966539", "definition": "中国水路运输领域的宏观政策导向、法律法规体系、政府规划及官方对水运方针政策的理论阐释与解读。", "boundary": "本节点聚焦于“政策与法规”层面，包括国家及地方关于水运发展的战略、条例、标准及官方解读。边界在于区分“政策制定”与“具体执行”（具体执行归入管理体制或建设发展）、“政策”与“市场行为”（企业自主经营归入企业经营管理）。若内容涉及政策对经济的影响分析，主挂载本节点；若涉及政策下的具体工程实施，归入建设与发展。", "includes": ["中国水路运输发展的战略规划、五年计划及长期目标", "水运相关法律法规、行政法规及部门规章", "官方对水运方针政策的理论阐述、背景分析及意义解读"], "excludes": ["具体的港口或航道工程技术细节", "企业内部的财务管理制度或操作流程", "世界或国际水路运输政策（归入世界水路运输经济）"], "sibling_distinctions": [{"other_code": "N_f82fa49c3de3be9f", "rule": "本节点侧重“规则与导向”（政策、法规、规划），兄弟节点侧重“组织与执行”（机构职能、管理架构、运行机制）。"}, {"other_code": "N_78f427df20e5ed77", "rule": "本节点侧重“宏观指导”（为什么做、做什么方向），兄弟节点侧重“实施过程”（怎么做、建设进度、发展现状）。"}], "cross_boundary_rule": "若内容涉及政策对具体建设项目的影响评估，主挂载本节点；若涉及项目本身的技术或经济核算，主挂载建设与发展或成本运价。"}, {"node_code": "N_f82fa49c3de3be9f", "definition": "中国水路运输行业的行政管理架构、行业监管机制、港口与航道管理机构职能及行业自律组织运作模式。", "boundary": "本节点聚焦于“管理组织与机制”，包括政府主管部门（如交通部门）的职能划分、海事管理机构、港口行政管理部门及行业协会的运作。边界在于区分“行政管理”与“企业经营管理”（企业归入企业组织和经营管理）、“管理”与“政策”（政策归入方针政策节点）。若内容涉及管理体制改革的历史演变，归入本节点。", "includes": ["中国水路运输行政管理体系及机构职能设置", "港口、航道、海事等具体管理领域的监管机制", "水运行业自律组织、协会及标准化管理体系"], "excludes": ["水路运输企业的内部人事、财务或市场营销管理", "水路运输工程的技术施工管理", "水路运输经济理论中的普适性管理原理"], "sibling_distinctions": [{"other_code": "N_506a3eef6d966539", "rule": "本节点侧重“谁在管、怎么管”（机构、职能、流程），兄弟节点侧重“管什么、依据什么”（政策、法规、规划）。"}, {"other_code": "N_6ede1a6d7030df85", "rule": "本节点侧重“行业公共管理”（政府、协会、监管），兄弟节点侧重“微观企业管理”（公司、船队、港口公司）。"}], "cross_boundary_rule": "若内容涉及管理体制改革的政策背景，主挂载方针政策；若涉及改革后的机构运作细节，主挂载管理体制。"}, {"node_code": "N_78f427df20e5ed77", "definition": "中国水路运输基础设施（航道、港口）的建设规划、投资效益、发展现状、未来趋势及综合运输体系中的水运地位分析。", "boundary": "本节点聚焦于“建设与发展”的经济与规划视角，包括水运网络布局、基础设施投资、产能扩张及发展瓶颈分析。边界在于区分“建设发展”与“工程技术”（具体施工技术归入工程节点）、“发展”与“历史”（历史归入交通史）。若内容涉及水运在综合运输中的经济比较优势，归入本节点。", "includes": ["中国航道、港口等水运基础设施的建设规划与投资分析", "中国水路运输能力发展现状、瓶颈及未来趋势预测", "水运在综合运输体系中的经济地位及多式联运发展策略"], "excludes": ["航道疏浚、港口机械等具体工程技术细节", "水路运输的历史沿革（归入中国水路交通史）", "具体的船舶调度或港口作业操作流程"], "sibling_distinctions": [{"other_code": "N_506a3eef6d966539", "rule": "本节点侧重“实施与结果”（建设进度、发展数据、趋势），兄弟节点侧重“指导与依据”（政策目标、法规要求）。"}, {"other_code": "N_bcd199fc6e3873c5", "rule": "本节点侧重“宏观发展”（网络、产能、投资），兄弟节点侧重“微观价格”（成本核算、运价制定、票价）。"}], "cross_boundary_rule": "若内容涉及建设项目的经济可行性分析，主挂载本节点；若涉及具体造价计算，可关联成本运价，但主挂载仍为建设发展。"}]}
